#include "KS/SRC/singleton_shared.h"

typedef unsigned int nslSourceId;
typedef unsigned int nslSoundId;

enum nslSoundStatusEnum {
    NSL_SOUNDSTATUS_INVALID = 0
};

nslSoundStatusEnum nslGetSoundStatus(nslSoundId sound);
void nslPauseSound(nslSoundId sound);

class Track {
    nslSourceId mySrcId;
    nslSoundId mySndId;
    bool paused;

public:
    char songName[30];
    char artistName[30];
    void Pause();
};

class MusicListing {
    int totalSources;
    int current;
    Track sources[50];
    nslSoundId currentSoundId;
    bool successfulLastPlay;

public:
    inline int getCurrent() const { return current; }
    inline nslSoundId getSoundId() const { return currentSoundId; }
    inline void pause() { sources[order[current]].Pause(); }
    int order[50];
    bool enabled[50];
};

template<class T>
class singleton_ptr {
    T *pointer;

public:
    inline operator T *() const { return pointer; }
};

class MusicMan : public singleton {
    float volume;
    int inited;
    bool paused;

public:
    static singleton_ptr<MusicMan> instance;

    static inline MusicMan *inst() { return instance; }

    MusicListing musicTrack;

    inline void pause()
    {
        if (!paused)
        {
            paused = true;
            musicTrack.pause();
        }
    }
};

class entity;

enum EventType {
    SS_FE_BACK = 27
};

class SoundScriptManager : public singleton {
public:
    static SoundScriptManager *instance;

    static inline SoundScriptManager *inst() { return instance; }
    void pause();
    void unpause();
    int playEvent(
        EventType type,
        entity *source = 0,
        float fade_in_time = 0.0f);
};

#include "KS/SRC/ks/FEMenu_shared.h"

class PauseMenuSystem : public FEMenuSystem {
public:
    bool draw;
    bool replay_mode;
    bool end_level;
    int pause_controller;
    int pause_player;
    void *map;
    TextString *player;
    int popupEvent;
    int navigationEvent;
};

class PlaylistMenuClass : public FEMenu {
    PauseMenuSystem *sys;

public:
    virtual void OnTriangle(int controller);
};

extern int pauseCount;

__asm__(".equ _8MusicMan$instance, 0x00427B18");
__asm__(".equ Pause__5Track, 0x002586E8");
__asm__(".equ _18SoundScriptManager$instance, 0x0046B4A0");
__asm__(".equ unpause__18SoundScriptManager, 0x0031BFA8");
__asm__(".equ playEvent__18SoundScriptManager9EventTypeP6entityf, 0x0031C380");
__asm__(".equ pause__18SoundScriptManager, 0x0031BF98");
__asm__(".equ pauseCount, 0x0040CE0C");
__asm__(".equ nslGetSoundStatus__FUi, 0x0038DBA0");
__asm__(".equ nslPauseSound__FUi, 0x0038D460");
__asm__(".equ OnTriangle__6FEMenui, 0x001577F0");

void PlaylistMenuClass::OnTriangle(int c)
{
	MusicMan::inst()->pause();
	SoundScriptManager::inst()->unpause();
	sys->navigationEvent=  SoundScriptManager::inst()->playEvent(SS_FE_BACK);
	SoundScriptManager::inst()->pause();
	while ((pauseCount > 0) && (nslGetSoundStatus(MusicMan::inst()->musicTrack.getSoundId()) != NSL_SOUNDSTATUS_INVALID))
	{
		nslPauseSound(MusicMan::inst()->musicTrack.getSoundId());
		pauseCount--;
	}
	FEMenu::OnTriangle(c);
}
